<?php
require_once __DIR__ . '/../bootstrap.php';require_once __DIR__.'/_google.php';require_method('POST');$u=require_auth(['super_admin']);require_csrf();$d=request_json();
$bid=(int)($d['business_id']??0);$summary=trim((string)($d['summary']??''));$cta=trim((string)($d['cta_url']??''));$image=trim((string)($d['image_url']??''));$account=preg_replace('/[^0-9]/','',(string)($d['account_id']??''));$location=preg_replace('/[^0-9]/','',(string)($d['location_id']??''));
if($bid&&(!$account||!$location)){$c=db()->prepare('SELECT account_id,location_id FROM gmb_connections WHERE business_id=? AND is_enabled=1');$c->execute([$bid]);if($x=$c->fetch()){$account=preg_replace('/[^0-9]/','',(string)$x['account_id']);$location=preg_replace('/[^0-9]/','',(string)$x['location_id']);}}
if(!$account||!$location||$summary==='')json_response(['ok'=>false,'error'=>'Connect a Google account/location and enter post text'],422);$body=['languageCode'=>'en-US','summary'=>$summary,'topicType'=>'STANDARD'];if($cta!=='')$body['callToAction']=['actionType'=>'LEARN_MORE','url'=>$cta];if($image!==''&&filter_var($image,FILTER_VALIDATE_URL))$body['media']=[['mediaFormat'=>'PHOTO','sourceUrl'=>$image]];
try{$r=gbp_request('POST',"https://mybusiness.googleapis.com/v4/accounts/{$account}/locations/{$location}/localPosts",$body);if($bid)audit((int)$u['id'],$bid,'gmb_post_published');json_response(['ok'=>true,'post'=>$r]);}catch(Throwable $e){json_response(['ok'=>false,'error'=>$e->getMessage()],502);}
